module truck_meeting(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire signed [7:0] a1,\n    input wire signed [7:0] a2,\n    input wire signed [7:0] b1,\n    input wire signed [7:0] b2,\n    output reg meeting,\n    output reg done\n);\n    // State definitions\n    localparam IDLE = 1'b0;\n    localparam DONE_ST = 1'b1;\n    \n    reg state;\n    reg meeting_reg;\n    \n    // Absolute difference calculations\n    wire signed [8:0] diff_a = a2 - a1;\n    wire signed [8:0] diff_b = b2 - b1;\n    wire [7:0] T1 = diff_a[8] ? (-diff_a[7:0]) : diff_a[7:0];\n    wire [7:0] T2 = diff_b[8] ? (-diff_b[7:0]) : diff_b[7:0];\n    \n    // Direction signals\n    wire signed [7:0] s1 = (a2 > a1) ? 8'sd1 : -8'sd1;\n    wire signed [7:0] s2 = (b2 > b1) ? 8'sd1 : -8'sd1;\n    \n    wire same_dir = (s1 == s2);\n    wire signed [8:0] numerator = b1 - a1;\n    wire signed [8:0] denominator = s1 - s2;\n    \n    // Additional calculations\n    wire [7:0] min_T = (T1 < T2) ? T1 : T2;\n    wire [8:0] two_min_T = {1'b0, min_T} << 1;\n    wire signed [8:0] two_min_T_s = $signed(two_min_T);\n    \n    // Meeting condition logic\n    wire meeting_calc = same_dir ? 1'b0 :\n        (denominator == 9'sd2) ? ((numerator > 9'sd0) && (numerator < two_min_T_s)) :\n        (denominator == -9'sd2) ? ((numerator < 9'sd0) && (numerator > (-two_min_T_s))) :\n        1'b0;\n    \n    // FSM control logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            meeting <= 1'b0;\n            done <= 1'b0;\n            meeting_reg <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        meeting_reg <= meeting_calc;\n                        state <= DONE_ST;\n                    end else begin\n                        state <= IDLE;\n                    end\n                end\n                \n                DONE_ST: begin\n                    meeting <= meeting_reg;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule